-- StreamGuard: normalized domain model. PostgreSQL 16+.
CREATE TABLE users (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), username VARCHAR(32) NOT NULL UNIQUE,
 email VARCHAR(254) NOT NULL UNIQUE, password_hash TEXT NOT NULL,
 status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED','DELETED')),
 created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE user_profiles (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, display_name VARCHAR(80) NOT NULL, bio TEXT NOT NULL DEFAULT '', avatar_url TEXT, locale VARCHAR(12) NOT NULL DEFAULT 'es-CO');
CREATE TABLE roles (id SMALLINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name VARCHAR(32) UNIQUE NOT NULL);
CREATE TABLE user_roles (user_id UUID REFERENCES users(id) ON DELETE CASCADE, role_id SMALLINT REFERENCES roles(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE auth_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE user_devices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, name VARCHAR(100), last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE user_consents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), purpose VARCHAR(100) NOT NULL, version VARCHAR(32) NOT NULL, accepted_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id,purpose,version));
CREATE TABLE channels (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_id UUID NOT NULL UNIQUE REFERENCES users(id), slug VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, description TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE channel_settings (channel_id UUID PRIMARY KEY REFERENCES channels(id) ON DELETE CASCADE, language VARCHAR(12) NOT NULL DEFAULT 'es', slow_mode_seconds INT NOT NULL DEFAULT 0 CHECK(slow_mode_seconds BETWEEN 0 AND 120), allow_links BOOLEAN NOT NULL DEFAULT false, auto_clips BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE channel_moderators (channel_id UUID REFERENCES channels(id) ON DELETE CASCADE, user_id UUID REFERENCES users(id) ON DELETE CASCADE, added_by UUID NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(channel_id,user_id));
CREATE TABLE channel_follows (channel_id UUID REFERENCES channels(id) ON DELETE CASCADE, user_id UUID REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(channel_id,user_id));
CREATE TABLE categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(64) NOT NULL UNIQUE, slug VARCHAR(64) NOT NULL UNIQUE);
CREATE TABLE tags (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE streams (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), channel_id UUID NOT NULL REFERENCES channels(id), category_id UUID REFERENCES categories(id), title VARCHAR(140) NOT NULL, description TEXT NOT NULL DEFAULT '', status VARCHAR(16) NOT NULL DEFAULT 'LIVE' CHECK(status IN ('LIVE','ENDED')), started_at TIMESTAMPTZ NOT NULL DEFAULT now(), ended_at TIMESTAMPTZ, CHECK(ended_at IS NULL OR ended_at >= started_at));
CREATE UNIQUE INDEX one_live_stream_per_channel ON streams(channel_id) WHERE status='LIVE';
CREATE TABLE stream_tags (stream_id UUID REFERENCES streams(id) ON DELETE CASCADE, tag_id UUID REFERENCES tags(id), PRIMARY KEY(stream_id,tag_id));
CREATE TABLE stream_viewer_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stream_id UUID NOT NULL REFERENCES streams(id), user_id UUID REFERENCES users(id), joined_at TIMESTAMPTZ NOT NULL DEFAULT now(), left_at TIMESTAMPTZ);
CREATE TABLE stream_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stream_id UUID NOT NULL REFERENCES streams(id), actor_id UUID REFERENCES users(id), event_type VARCHAR(40) NOT NULL, payload JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE chat_rooms (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stream_id UUID NOT NULL UNIQUE REFERENCES streams(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE chat_messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), room_id UUID NOT NULL REFERENCES chat_rooms(id), user_id UUID NOT NULL REFERENCES users(id), content VARCHAR(1000) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','VISIBLE','HIDDEN','REVIEW')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE message_reactions (message_id UUID REFERENCES chat_messages(id) ON DELETE CASCADE, user_id UUID REFERENCES users(id), reaction VARCHAR(24) NOT NULL, PRIMARY KEY(message_id,user_id,reaction));
CREATE TABLE message_reports (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), message_id UUID NOT NULL REFERENCES chat_messages(id), reporter_id UUID NOT NULL REFERENCES users(id), reason VARCHAR(500) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(message_id,reporter_id));
CREATE TABLE moderation_policies (channel_id UUID PRIMARY KEY REFERENCES channels(id), level VARCHAR(16) NOT NULL DEFAULT 'BALANCED' CHECK(level IN ('RELAXED','BALANCED','STRICT')), auto_hide BOOLEAN NOT NULL DEFAULT true, auto_mute BOOLEAN NOT NULL DEFAULT false, mute_seconds INT NOT NULL DEFAULT 300 CHECK(mute_seconds BETWEEN 30 AND 86400), review_threshold NUMERIC(3,2) NOT NULL DEFAULT 0.55 CHECK(review_threshold BETWEEN 0 AND 1), block_threshold NUMERIC(3,2) NOT NULL DEFAULT 0.85 CHECK(block_threshold BETWEEN 0 AND 1), CHECK(block_threshold >= review_threshold));
CREATE TABLE blocked_words (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), channel_id UUID NOT NULL REFERENCES channels(id) ON DELETE CASCADE, word VARCHAR(80) NOT NULL, UNIQUE(channel_id,word));
CREATE TABLE blocked_topics (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), channel_id UUID NOT NULL REFERENCES channels(id) ON DELETE CASCADE, topic VARCHAR(120) NOT NULL, UNIQUE(channel_id,topic));
CREATE TABLE moderation_rules (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), channel_id UUID NOT NULL REFERENCES channels(id), category VARCHAR(40) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true, action VARCHAR(16) NOT NULL CHECK(action IN ('WARN','HIDE','MUTE','REVIEW')), UNIQUE(channel_id,category));
CREATE TABLE ai_providers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(40) NOT NULL UNIQUE, base_url TEXT NOT NULL);
CREATE TABLE ai_models (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), provider_id UUID NOT NULL REFERENCES ai_providers(id), name VARCHAR(80) NOT NULL, capabilities JSONB NOT NULL DEFAULT '[]', UNIQUE(provider_id,name));
CREATE TABLE ai_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stream_id UUID REFERENCES streams(id), model_name VARCHAR(80) NOT NULL, task VARCHAR(40) NOT NULL, input JSONB NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SUCCEEDED','FAILED','LOCAL')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ai_responses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_id UUID NOT NULL UNIQUE REFERENCES ai_requests(id), output JSONB NOT NULL, latency_ms INT NOT NULL CHECK(latency_ms >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE message_classifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), message_id UUID NOT NULL UNIQUE REFERENCES chat_messages(id), request_id UUID REFERENCES ai_requests(id), category VARCHAR(40) NOT NULL, confidence NUMERIC(4,3) NOT NULL CHECK(confidence BETWEEN 0 AND 1), reason VARCHAR(500) NOT NULL, provider VARCHAR(40) NOT NULL);
CREATE TABLE moderation_queue (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), message_id UUID NOT NULL UNIQUE REFERENCES chat_messages(id), status VARCHAR(16) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED')), reviewer_id UUID REFERENCES users(id), reviewed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE moderation_actions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), channel_id UUID NOT NULL REFERENCES channels(id), message_id UUID REFERENCES chat_messages(id), actor_id UUID REFERENCES users(id), target_id UUID NOT NULL REFERENCES users(id), action VARCHAR(16) NOT NULL CHECK(action IN ('HIDE','APPROVE','WARN','MUTE','BAN','REVOKE')), reason VARCHAR(500) NOT NULL, automated BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE user_sanctions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), channel_id UUID NOT NULL REFERENCES channels(id), user_id UUID NOT NULL REFERENCES users(id), action_id UUID REFERENCES moderation_actions(id), type VARCHAR(16) NOT NULL CHECK(type IN ('MUTE','BAN')), expires_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sanction_appeals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sanction_id UUID NOT NULL REFERENCES user_sanctions(id), user_id UUID NOT NULL REFERENCES users(id), explanation TEXT NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'PENDING', reviewer_id UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE user_warnings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), channel_id UUID NOT NULL REFERENCES channels(id), user_id UUID NOT NULL REFERENCES users(id), action_id UUID REFERENCES moderation_actions(id), reason VARCHAR(500) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE media_assets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_id UUID NOT NULL REFERENCES users(id), storage_key TEXT NOT NULL UNIQUE, mime_type VARCHAR(64) NOT NULL, size_bytes BIGINT NOT NULL CHECK(size_bytes > 0), duration_seconds NUMERIC(9,2), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE recording_segments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stream_id UUID NOT NULL REFERENCES streams(id), asset_id UUID NOT NULL UNIQUE REFERENCES media_assets(id), start_seconds INT NOT NULL CHECK(start_seconds >= 0), end_seconds INT NOT NULL, CHECK(end_seconds > start_seconds));
CREATE TABLE stream_highlights (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stream_id UUID NOT NULL REFERENCES streams(id), marked_by UUID REFERENCES users(id), source VARCHAR(24) NOT NULL CHECK(source IN ('MANUAL','CHAT_SPIKE','AUDIO_PEAK','AI')), at_seconds INT NOT NULL CHECK(at_seconds >= 0), score NUMERIC(5,2) NOT NULL DEFAULT 1, reason VARCHAR(500) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE clips (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stream_id UUID NOT NULL REFERENCES streams(id), highlight_id UUID REFERENCES stream_highlights(id), asset_id UUID REFERENCES media_assets(id), title VARCHAR(140) NOT NULL, description TEXT NOT NULL DEFAULT '', start_seconds INT NOT NULL CHECK(start_seconds >= 0), end_seconds INT NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(end_seconds > start_seconds));
CREATE TABLE clip_versions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), clip_id UUID NOT NULL REFERENCES clips(id), asset_id UUID REFERENCES media_assets(id), editor_id UUID NOT NULL REFERENCES users(id), title VARCHAR(140) NOT NULL, description TEXT NOT NULL DEFAULT '', start_seconds INT NOT NULL, end_seconds INT NOT NULL CHECK(end_seconds > start_seconds), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE clip_tags (clip_id UUID REFERENCES clips(id) ON DELETE CASCADE, tag_id UUID REFERENCES tags(id), PRIMARY KEY(clip_id,tag_id));
CREATE TABLE clip_reviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), clip_id UUID NOT NULL REFERENCES clips(id), reviewer_id UUID NOT NULL REFERENCES users(id), decision VARCHAR(16) NOT NULL CHECK(decision IN ('APPROVED','REJECTED')), note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE clip_exports (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), clip_id UUID NOT NULL REFERENCES clips(id), asset_id UUID REFERENCES media_assets(id), requested_by UUID NOT NULL REFERENCES users(id), format VARCHAR(24) NOT NULL DEFAULT 'webm', status VARCHAR(16) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE clip_shares (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), clip_id UUID NOT NULL REFERENCES clips(id), shared_by UUID NOT NULL REFERENCES users(id), platform VARCHAR(40) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE stream_summaries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stream_id UUID NOT NULL REFERENCES streams(id), request_id UUID REFERENCES ai_requests(id), content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE stream_topics (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stream_id UUID NOT NULL REFERENCES streams(id), label VARCHAR(120) NOT NULL, relevance NUMERIC(4,3) NOT NULL CHECK(relevance BETWEEN 0 AND 1), UNIQUE(stream_id,label));
CREATE TABLE transcripts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stream_id UUID NOT NULL REFERENCES streams(id), asset_id UUID REFERENCES media_assets(id), language VARCHAR(12) NOT NULL DEFAULT 'es', source VARCHAR(24) NOT NULL CHECK(source IN ('BROWSER','GEMINI','HUMAN')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE subtitle_cues (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transcript_id UUID NOT NULL REFERENCES transcripts(id) ON DELETE CASCADE, start_seconds NUMERIC(9,2) NOT NULL CHECK(start_seconds >= 0), end_seconds NUMERIC(9,2) NOT NULL, text TEXT NOT NULL, CHECK(end_seconds > start_seconds));
CREATE TABLE chat_faqs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stream_id UUID NOT NULL REFERENCES streams(id), question TEXT NOT NULL, answer TEXT NOT NULL, occurrences INT NOT NULL DEFAULT 1 CHECK(occurrences > 0), request_id UUID REFERENCES ai_requests(id));
CREATE TABLE stream_analytics (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stream_id UUID NOT NULL REFERENCES streams(id), bucket_at TIMESTAMPTZ NOT NULL, viewers INT NOT NULL DEFAULT 0 CHECK(viewers >= 0), messages INT NOT NULL DEFAULT 0 CHECK(messages >= 0), blocked INT NOT NULL DEFAULT 0 CHECK(blocked >= 0), UNIQUE(stream_id,bucket_at));
CREATE TABLE audience_reactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stream_id UUID NOT NULL REFERENCES streams(id), user_id UUID NOT NULL REFERENCES users(id), reaction VARCHAR(24) NOT NULL, at_seconds INT NOT NULL CHECK(at_seconds >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), type VARCHAR(40) NOT NULL, title VARCHAR(140) NOT NULL, body TEXT NOT NULL, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notification_preferences (user_id UUID PRIMARY KEY REFERENCES users(id), email_enabled BOOLEAN NOT NULL DEFAULT false, moderation_enabled BOOLEAN NOT NULL DEFAULT true, clips_enabled BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_id UUID REFERENCES users(id), entity_type VARCHAR(40) NOT NULL, entity_id UUID, action VARCHAR(40) NOT NULL, details JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE channel_webhooks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), channel_id UUID NOT NULL REFERENCES channels(id), url TEXT NOT NULL, event_type VARCHAR(40) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE webhook_deliveries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), webhook_id UUID NOT NULL REFERENCES channel_webhooks(id), event_id UUID REFERENCES stream_events(id), status_code INT, attempts INT NOT NULL DEFAULT 0 CHECK(attempts >= 0), delivered_at TIMESTAMPTZ);
CREATE TABLE subscription_plans (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(40) NOT NULL UNIQUE, price_cents INT NOT NULL CHECK(price_cents >= 0), features JSONB NOT NULL DEFAULT '{}');
CREATE TABLE channel_subscriptions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), channel_id UUID NOT NULL REFERENCES channels(id), user_id UUID NOT NULL REFERENCES users(id), plan_id UUID NOT NULL REFERENCES subscription_plans(id), starts_at TIMESTAMPTZ NOT NULL DEFAULT now(), ends_at TIMESTAMPTZ, UNIQUE(channel_id,user_id));
CREATE TABLE badges (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(40) NOT NULL UNIQUE, icon VARCHAR(80) NOT NULL);
CREATE TABLE user_badges (user_id UUID REFERENCES users(id), badge_id UUID REFERENCES badges(id), granted_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(user_id,badge_id));
CREATE TABLE emotes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), creator_id UUID REFERENCES users(id), code VARCHAR(32) NOT NULL UNIQUE, asset_id UUID REFERENCES media_assets(id));
CREATE TABLE channel_emotes (channel_id UUID REFERENCES channels(id), emote_id UUID REFERENCES emotes(id), PRIMARY KEY(channel_id,emote_id));
CREATE TABLE playlists (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), channel_id UUID NOT NULL REFERENCES channels(id), name VARCHAR(100) NOT NULL, public BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE playlist_items (playlist_id UUID REFERENCES playlists(id) ON DELETE CASCADE, clip_id UUID REFERENCES clips(id), position INT NOT NULL CHECK(position >= 0), PRIMARY KEY(playlist_id,clip_id), UNIQUE(playlist_id,position));

CREATE INDEX sessions_user ON auth_sessions(user_id,expires_at);
CREATE INDEX streams_status ON streams(status,started_at DESC);
CREATE INDEX messages_room_time ON chat_messages(room_id,created_at DESC);
CREATE INDEX messages_user_time ON chat_messages(user_id,created_at DESC);
CREATE INDEX queue_pending ON moderation_queue(status,created_at);
CREATE INDEX sanctions_active ON user_sanctions(channel_id,user_id) WHERE revoked_at IS NULL;
CREATE INDEX clips_stream_status ON clips(stream_id,status);
CREATE INDEX highlights_stream ON stream_highlights(stream_id,at_seconds);
CREATE INDEX requests_stream ON ai_requests(stream_id,created_at DESC);
CREATE INDEX events_payload ON stream_events USING GIN(payload);
CREATE INDEX audit_time ON audit_logs(created_at DESC);

